# Let's find which class has the most "suspicious" channels (high positive FC weight + high positive conv3 bias)
fc_w = W['fc.weight']
conv3_b = W['conv3.bias']

# For each class, count channels with fc_weight > 0.4 AND bias > 0.2
print("Channels with fc_weight > 0.4 and conv3_bias > 0.2 per class:")
for c in range(10):
    count = 0
    channels = []
    for ch in range(64):
        if fc_w[c, ch] > 0.4 and conv3_b[ch] > 0.2:
            count += 1
            channels.append((ch, fc_w[c, ch].item(), conv3_b[ch].item()))
    if count > 0:
        print(f"Class {c} ({CLASSES[c]}): {count} channels")
        for ch, fw, b in channels:
            print(f"  Ch {ch}: fc={fw:.4f}, bias={b:.4f}")

